 \label{lem:symmetries}


Let $\mathbf{P} = \mathbf{NOP}$, then for all $\theta, \varphi, \alpha \in \mathbb{R}$, the following three identities hold (as sets):
\begin{align*}
    M({\theta+2\pi/15,\varphi})\cdot \mathbf{P} &=M(\theta, \varphi) \cdot \mathbf{P},\\
    R(\alpha+\pi)M(\theta, \varphi) \cdot \mathbf{P} &=R(\alpha)M(\theta, \varphi) \cdot \mathbf{P},\\
    \begin{pmatrix}
        1&0\\
        0&-1
    \end{pmatrix}
    M(\theta, \varphi) \cdot \mathbf{P}&=
    M({\theta+\pi/15,\pi-\varphi}) \cdot \mathbf{P}.
\end{align*}

\label{cor:rupert_tightening}


